#include "os.h"
#include "idb_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Idb idb_create (Boolean pin_level , UInt16 time_0_to_1 , UInt16 time_1_to_0)
{
  Idb idb = (Idb) os_mem_request (sizeof *idb) ;

  idb->_0_to_1_.time = time_0_to_1 ;
  idb->_1_to_0_.time = time_1_to_0 ;

  idb_set_level (idb , pin_level) ;

  return idb ;
}

